{
  "findings": [
    {
      "check_id": "CKV_AWS_260",
      "title": "Security Group allows ingress from 0.0.0.0/0",
      "resource": "aws_security_group.lb",
      "severity": "CRITICAL",
      "explanation": "The security group allows incoming traffic from all IP addresses on all ports and protocols, potentially exposing the load balancer to unauthorized access."
    }
  ],
  "patched_code": "resource "aws_security_group" "lb" {
  name   = "allow-all-lb"
  vpc_id = data.aws_vpc.main.id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}",
  "fix_summary": "Restricted the ingress rule to only allow HTTP and HTTPS traffic from 0.0.0.0/0, instead of all ports and protocols."
}
